from google.cloud import speech

def get_speech_client():
    return speech.SpeechClient()

from typing import Dict, Any

def create_recognition_config(language_code: str, enable_speaker_diarization: bool = False, enable_word_time_offsets: bool = False) -> Dict[str, Any]:
    config = {
        "language_code": language_code,
    }
    if enable_speaker_diarization:
        config["enable_speaker_diarization"] = True
        config["diarization_speaker_count"] = 2 # Default to 2 speakers
    if enable_word_time_offsets:
        config["enable_word_time_offsets"] = True
    return config

def create_recognition_audio(audio_uri: str) -> Dict[str, Any]:
    return {
        "uri": audio_uri
    }

def normalize_transcript_result(operation_name: str, response: Dict[str, Any]) -> Dict[str, Any]:
    # Basic normalization, could be expanded based on specific needs
    return {
        "job_id": operation_name,
        "status": "COMPLETED" if response.get("done") else "IN_PROGRESS",
        "transcript": response.get("response", {}).get("results", [])
    }

from speech_client import get_speech_client
from speech_models import normalize_transcript_result

def poll_transcription(job_id: str):
    client = get_speech_client()
    operation = client.get_operation(name=job_id)

    if operation.done:
        return normalize_transcript_result(job_id, operation.to_dict())
    else:
        return {
            "job_id": job_id,
            "status": "IN_PROGRESS",
        }

from google.cloud import speech
from speech_client import get_speech_client
from speech_models import create_recognition_config, create_recognition_audio

def diarized_transcript(payload: dict, config: dict = None):
    config = config or {}
    client = get_speech_client()

    recognition_config = create_recognition_config(
        language_code=payload["language_code"],
        enable_speaker_diarization=True,
    )
    audio = create_recognition_audio(payload["audio_uri"])

    operation = client.long_running_recognize(
        config=speech.RecognitionConfig(**recognition_config),
        audio=speech.RecognitionAudio(**audio),
    )

    return {
        "job_id": operation.operation.name,
        "status": "SUBMITTED",
    }

